pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let post = post_residual as f64;

    // Base score: prioritize Best-Fit (smaller post_residual).
    // We penalize larger residuals quadratically to prefer tighter packing.
    let mut score = post * post * 0.01;

    // Penalty for opening a new bin:
    // If this is a new bin (bin_residual == bin_capacity), add a significant penalty
    // that scales with progress (as we reach the end, we are more desperate to pack tightly).
    if bin_residual == bin_capacity {
        score += 50.0 + (progress * 50.0);
    }

    // Lookahead logic:
    // If we have a next item, penalize leaving a residual that is too small to fit the next item
    // but large enough to waste space (the "dangling fragment" problem).
    if next_item_size > 0 {
        if post < next_item_size as f64 && post > 0.0 {
            // This creates a "dead zone" for the next item, penalize it non-linearly.
            score += (next_item_size as f64 / (post + 1.0)).powf(1.5);
        }
    }

    // Pressure to consolidate:
    // If we are opening too many bins relative to the mean residual, 
    // penalize the creation of new bins/loose bins.
    if open_bins_count as f64 > (100.0 / (mean_residual + 1.0)) {
        score += (open_bins_count as f64) * 0.5;
    }

    // Final adjustment:
    // Favor bins that result in residuals close to zero, 
    // especially as the stream progresses.
    score -= (1.0 - progress) * (bin_capacity as f64 - post) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    // Harmonic-inspired heuristic:
