    // This helps group items into uniform residual states
    let remainder = post_residual % 20;
    if remainder == 0 {
        score -= 10.0;
    } else {
        score += remainder as f64 * 0.5;
    }

    // New bin threshold logic:
    // If this is an empty bin (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
