    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // If the post_residual can hold the next item, reduce score to prioritize this bin.
            score -= 25.0 * (next_item_size as f64 / 100.0);
        } else {
            // If the post_residual is too small for the next item, penalize it slightly
            // to favor bins that leave room for the next item.
            score += 10.0;
        }
    }

    // 3. Mean Residual Alignment: 
    // Penalize bins that deviate significantly from the mean_residual of open bins.
    // This helps maintain a uniform "tightness" across all bins.
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.5;

    // 4. Scarcity Factor:
    // If this is the only bin that can fit the item, prioritize it to save space for larger items.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // 5. Progression factor:
    // As we approach the end of the stream, be more aggressive about filling bins (minimizing residuals).
    let progress = step_index as f64 / total_items as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
