    let post = post_residual as f64;

    // Penalize creating small unusable gaps (1-9) which are hard to fill later.
    // The penalty is modulated by progress, becoming more strict towards the end of the stream.
    let fragmentation_penalty = if post > 0.0 && post < 10.0 {
        (10.0 - post) * (1.0 + progress * 2.0)
    } else {
        0.0
    };

    // Reward bins that keep the post_residual close to the mean_residual of existing bins
    // to maintain uniformity, which helps in standardizing bin utilization.
    let uniformity_bonus = (post - mean_residual).abs() * 0.5;

