    };

    // If this is the only bin that fits, we should heavily prefer it to avoid opening a new one,
    // unless the fit is extremely poor (high post_residual).
    let fit_urgency = if fitting_bins_count == 1 { -50.0 } else { 0.0 };

    // New bin candidate indicator (bin_residual == bin_capacity)
    // We penalize opening a new bin significantly unless the current fit is terrible.
    let new_bin_penalty = if bin_residual == bin_capacity {
