        let mean_ratio = mean_residual / bin_capacity as f64;
        let proximity_to_mean = 1.0 - (residual_ratio - mean_ratio).abs();

        score -= 42.0 * proximity_to_mean;

        // Prioritize filling the tightest bin (Best-Fit reinforcement)
        if fitting_bins_count == 1 {
            score -= 88.0;
        }
    }

    // Advanced Lookahead:
    // If next_item_size is large, we now heavily penalize bin configurations that would 
    // leave the bin in a "dead zone" (e.g., residual < 15% of capacity)
    if next_item_size > 0 {
        let utilization = 1.0 - (post_residual as f64 / bin_capacity as f64);
        if post_residual >= next_item_size {
            let slack_after_next = post_residual - next_item_size;
            score -= 52.0 * (1.0 - (slack_after_next as f64 / bin_capacity as f64).powf(0.5));
        } else {
            // Increased penalty for blocking the next item
            score += 68.0 * (next_item_size as f64 / bin_capacity as f64) * utilization;
        }
    }

    // Refined Entropy dampener: tighter control over open bins count
    // Lowered transition threshold to 0.48 to start aggressive packing earlier
    let entropy_factor = if progress < 0.48 { 0.42 } else { 2.45 };
    score += (open_bins_count as f64) * entropy_factor;

    // Fragmentation avoidance: aggressive penalty for "unfillable" small residuals
    // Penalizing residual range [1, 12] more heavily than the parent to reduce stragglers
    if post_residual > 0 && post_residual < 13 {
        score += 28.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 1. Reward tight packing: If post_residual is very small, prioritize it (Best Fit).
    // We heavily penalize large post_residuals that create "dead space".
    score += (post_residual as f64).powf(1.5);

    // 2. Lookahead matching: If next_item_size fits in the post_residual, drastically reduce the score.
    // This rewards bins that can accommodate the very next item.
    if next_item_size > 0 && post_residual >= next_item_size {
