        let waste_after_next = (post_residual - next_item_size) as f64;
        score += waste_after_next * 2.0;
    }

    // 3. Penalty for opening new bins: If this is a new bin, apply a significant penalty.
    // Only open a new bin if the existing options are extremely poor (high post_residual).
    if bin_residual == bin_capacity {
