    }

    // 3. New Bin Threshold Logic:
    // Only open a new bin if the current bin is empty (bin_residual == bin_capacity).
    // We penalize this based on total_items remaining and current open_bins_count.
    if bin_residual == bin_capacity {
        let completion_ratio = step_index as f64 / total_items as f64;
        // Increase penalty for new bins as the process nears completion to avoid fragmentation
        let new_bin_penalty = 55.0 + (completion_ratio * 40.0) + (open_bins_count as f64 * 2.5);
        score += new_bin_penalty;
    }

    // 4. Mean Residual Awareness:
    // If the current bin's post_residual is better than the global mean, reward it to encourage convergence.
    if (post_residual as f64) < mean_residual {
        score -= 12.0;
    }

    // 5. Urgency Constraint: 
    // Do not penalize the ONLY available bin that fits the current item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // 6. Fragmentation Penalty:
    // Specifically target small slivers that are useless for most items.
    if post_residual > 0 && post_residual < 6 {
        score += 25.0;
    }

    score
}

