    // 3. Adaptive New-Bin Threshold:
    // The penalty for a new bin grows as the stream progresses, but is mitigated
    // if the current mean_residual is high (indicating we are wasting too much space in existing bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let base_penalty = 50.0 + (progress * 40.0);
        let efficiency_modifier = (mean_residual / bin_capacity as f64) * 30.0;
        score += (base_penalty - efficiency_modifier).max(10.0);
