    // 3. Density Balancing:
    // If the bin's residual is significantly better than the current mean_residual,
    // it's a high-quality bin; we want to fill it up further.
    if (post_residual as f64) < mean_residual {
        score -= 15.0;
    }

    // 4. Scarcity Constraint:
    // If this is the only bin that can fit the item, we must take it, 
