    // 5. Fragmentation Mitigation:
    // Penalize bins that would end up with a residual in the "danger zone" (e.g., 5-15)
    // where they are too small for most items but too large to be considered "packed".
    if post_residual >= 5 && post_residual <= 15 {
        score += 8.0;
    }

    score
