        }
    } else {
        // If we are filling an existing bin, favor those that bring the residual
        // closer to the global mean, promoting uniform bin density.
        score += ((post_residual as f64 - mean_residual).abs()) * 0.25;
    }

    // 3. Dynamic End-Game Pressure:
    // As total_items approaches, the cost of opening a new bin outweighs
    // the benefit of a "perfect" local fit.
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.85 {
