        score += (post_residual as f64) * 0.8;
    }

    // 4. Harmonic Resonance:
    // Penalize odd residuals that are hard to fill. Target 25/50 as clean breakpoints.
    let remainder = post_residual % 25;
    if remainder != 0 {
        score += remainder as f64 * 0.4;
    }

    // 5. Fitting Context:
    // If this is the only bin that can house the item, reward it to lock it in.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
