        // Incentivize using bins that are already well-utilized to keep high-density clusters
        score -= (bin_capacity - bin_residual) as f64 * 0.48;
    }

    // 3. Dynamic Thresholding: Stricter barrier for opening new bins
    // Increases the cost of a new bin based on current system density and progress
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        let density_factor = (open_bins_count as f64).powf(1.12) / (1.0 + (step_index as f64).sqrt() * 0.32);
        // Stricter utilization penalty for early/mid game
        let utilization_penalty = if mean_residual < (bin_capacity as f64 * 0.50) { 280.0 } else { 130.0 };
        score += utilization_penalty * (1.0 + density_factor * (1.0 - progress).powf(0.8));
    }

    // 4. Entropy Reduction: Favor residuals that align with common item sizes (mod 20)
    // Shifted penalty to encourage larger, more usable residual blocks
    let alignment_penalty = ((post_residual % 20) as f64) * 2.1;
    score += alignment_penalty;

    // 5. Temporal Decay: Aggressive compaction heuristic
    let progress = step_index as f64 / total_items as f64;
    if progress > 0.95 {
