        }
        // If not in a perfect fit, favor maintaining slightly larger residual capacity
        // to maximize flexibility for unknown item distribution
        score -= (bin_capacity - post_residual) as f64 * 0.10;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score is the remaining space (Best Fit principle)
    let mut score = post_residual as f64;

    // Penalty for creating a "small" residual that is unlikely to fit future items (dead space)
    // We penalize exponentially as post_residual approaches 0, but only if it's not a perfect fit.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 / (post_residual as f64).powf(1.5);
