        score += 35.0;

        // Dynamic adjustment: As we reach the end of the stream, prioritize packing tightly 
        // into existing bins to avoid leaving too many underutilized bins.
        score += (progress * 40.0);

        // If we have plenty of open bins, discourage opening another unless necessary
        score += (open_bins_count as f64) * 2.5;
    } else {
        // Reward bins that bring the current residual closer to the global mean, 
        // promoting uniform bin usage.
        let deviation = (post_residual as f64 - mean_residual).abs();
        score += deviation * 0.5;
    }

    // If this is the last chance for this item (fitting_bins_count == 1), 
    // heavily favor placing it here rather than opening a new bin.
    if !is_new_bin && fitting_bins_count == 1 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
