    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Favor tighter residual packing, slightly increased sensitivity
    let mut score = post_residual as f64 * 0.78;

    // 1. Predictive Lookahead: Enhanced sensitivity to "Next Item" fitment
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            // Encourage perfect fits for the immediate next item
            score -= 410.0 * (1.0 - (slack as f64 / bin_capacity as f64).powf(0.6));
        } else if post_residual > 0 {
            // Penalize fragmentation that blocks the next item
            score += 480.0 * (1.0 - (post_residual as f64 / next_item_size as f64).powf(2.1));
        }
    }

    // 2. Dead Space Mitigation: Target "slivers" that are too small to be useful
    if post_residual > 0 && post_residual <= 32 {
        let scarcity_factor = if fitting_bins_count < 9 { 5.5 } else { 2.8 };
        score += (710.0 / (post_residual as f64).powf(0.95)) * scarcity_factor;
    }

    // 3. Adaptive Bin Opening: Dynamic cost based on stream velocity
    if is_new_bin {
        // Higher resistance to opening new bins
        let density_factor = 1.0 - (open_bins_count as f64 / (step_index as f64 / 8.0 + 7.5).sqrt());
        let efficiency_penalty = (mean_residual / bin_capacity as f64) * 1450.0;
        score += efficiency_penalty * (1.0 + (progress * 9.5)) * density_factor.max(0.38);
    } else {
        // Consolidation reward: stronger pull toward filling deep bins
        score -= (bin_capacity - bin_residual) as f64 * 1.35;
    }

    // 4. Tight Packing Rewards:
    if post_residual == 0 {
        score -= 900.0; 
    } else if post_residual < 16 {
        score -= 280.0 * (1.0 - (post_residual as f64 / 16.0));
    }

    // 5. Global Compaction Strategy:
    if progress > 0.92 {
        score += (post_residual as f64) * 115.0;
        if is_new_bin {
            score += 3300.0; 
        }
    } else if post_residual > 10 && post_residual < 75 {
        // Mid-game: prevent premature fragmentation by favoring existing bins
        if open_bins_count < 40 {
            score -= 230.0;
        }
    }

    // 6. Entropy stabilizer: Adaptive penalty for active bin count
    let entropy_penalty = (open_bins_count as f64).powf(0.55) * (mean_residual / bin_capacity as f64) * 110.0;
    score += entropy_penalty;

    // 7. Residual Variance dampener:
    // Force uniform filling across bins to prevent early exhaustion of capacity
    if post_residual as f64 > (mean_residual + 14.0) {
        score += 150.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(0.42));
    }

    score
}

