            } else {
                // If the next item won't fit, penalize based on how "useless" the remaining space is
                score += (100.0 - post) * 0.5;
            }
        }

        // Encourage balanced filling: penalize bins that deviate significantly from the mean_residual
        let deviation = (post - mean_residual).abs();
        score += deviation * 0.2;
    }

    // Criticality check: if this is the only bin that can fit the item, prioritize it heavily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base score: Favor filling space with a slightly higher weighting on the post-residual
    let mut score = post_residual as f64 * 0.76;

    // 1. Predictive Lookahead: Refined for tighter fitment
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 440.0 * (1.0 - (slack as f64 / bin_capacity as f64).sqrt());
        } else if post_residual > 0 {
            score += 460.0 * (1.0 - (post_residual as f64 / next_item_size as f64).powf(2.2));
        }
    }

    // 2. Dead Space Mitigation: Target smaller, more problematic slivers
    if post_residual > 0 && post_residual <= 26 {
        let scarcity_factor = if fitting_bins_count < 7 { 5.8 } else { 2.9 };
        score += (760.0 / (post_residual as f64).powf(0.94)) * scarcity_factor;
    }

    // 3. Adaptive Bin Opening: Stronger push against opening new bins when mean_residual is high
    if is_new_bin {
        let density_factor = 1.0 - (open_bins_count as f64 / (step_index as f64 / 9.0 + 8.0).sqrt());
        let efficiency_penalty = (mean_residual / bin_capacity as f64) * 1650.0;
        score += efficiency_penalty * (1.0 + (progress * 7.0)) * density_factor.max(0.28);
    } else {
        // Consolidation: reward filling existing bins to reduce total active bin count
        score -= (bin_capacity - bin_residual) as f64 * 1.35;
    }

    // 4. Tight Packing Rewards:
    if post_residual == 0 {
        score -= 950.0; 
    } else if post_residual < 10 {
        score -= 300.0 * (1.0 - (post_residual as f64 / 10.0));
    }

    // 5. Global Compaction Strategy:
    if progress > 0.90 {
        score += (post_residual as f64) * 130.0;
        if is_new_bin {
            score += 3500.0; 
        }
    } else if post_residual > 15 && post_residual < 65 {
        if open_bins_count < 25 {
            score -= 250.0;
        }
    }

    // 6. Entropy stabilizer: Adaptive penalty for active bin count
    let entropy_penalty = (open_bins_count as f64).sqrt() * (mean_residual / bin_capacity as f64) * 110.0;
    score += entropy_penalty;

    // 7. Residual Variance dampener: 
    if post_residual as f64 > (mean_residual + 12.0) {
        score += 150.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powf(0.58));
    }

    // 8. Final adjustment: reward deep packing to minimize fragmentation
    if post_residual < 4 && !is_new_bin {
        score -= 200.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalty for creating "dead space" that is too small for common items (below 10)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Heuristic: If we are near the end of the stream, prioritize aggressive packing (Best Fit)
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * (post_residual as f64 * 0.5);

    // Lookahead logic: if next_item_size is large, favor bins that can accommodate it.
    // If post_residual is smaller than the next item, we penalize the current choice.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 15.0;
        } else {
            // Reward bins that leave exactly enough space for the next item
            score -= (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    // Harmonic logic: penalize bins that deviate significantly from the mean_residual
    // to keep bin fill levels balanced (reduces variance in bin usage).
    let deviation = (post_residual as f64 - mean_residual).abs();
    score += deviation * 0.1;

    // Logic for new bin (bin_residual == bin_capacity):
    // Only open a new bin if the current "best" fit is extremely poor (post_residual < 10)
    // or if we have very few open bins (encouraging consolidation).
    if bin_residual == bin_capacity {
        if open_bins_count == 0 {
            score = -100.0; // Must open first bin
        } else if fitting_bins_count == 0 {
            score = 0.0; // Must open new bin if nothing fits
        } else {
            // High threshold to prevent opening new bins unnecessarily
            score = 45.0 + (progress * 20.0);
        }
    }

    score
}

