    // Objective: Minimize post_residual, but heavily penalize small "unusable" gaps (1..9) 
    // that are too small for most items, and account for lookahead and bin count pressure.

    let mut score = post_residual as f64;

    // 1. Dead space penalty: If the post_residual is in the range [1, 9], it is highly unlikely
    // to fit future items. We apply a significant penalty to force the algorithm to prefer
    // bins that result in either 0 residual or a larger, more flexible residual.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0; 
